#!/bin/env bash

set -eo pipefail

DEBUG=0

if [[ $DEBUG -eq 1 ]]; then
	set -x
fi

SCRIPT_DIR="$(cd -P "$(dirname "$0")" && pwd)"
. "$SCRIPT_DIR/utils.sh"

# Name of the multiband compressor node inside the filter chain, as generated by ee2pw.
MB_COMPRESSOR="${MB_COMPRESSOR:-multiband_compressor_0}"

SUBCOMMANDS="help, enable, disable, set-input-gain, set-output-gain, set-gains, set-makeup-gain, set-split-frequency, set-solo, set-mute, set-band-enabled, set-band-compressor"

help() {
	echo "Usage: $0 <node_name> <subcommand> [options]"
	echo ""
	echo "Available subcommands:"
	echo "  help                   Show this help message"
	echo "  enable                 Enable multiband compressor for node"
	echo "  disable                Disable multiband compressor for node"
	echo "  set-input-gain         Set input gain in dB"
	echo "  set-output-gain        Set output gain in dB"
	echo "  set-gains              Set input gain, makeup gains and split frequencies from a file"
	echo "  set-makeup-gain        Set makeup gain for a specific band in dB"
	echo "  set-split-frequency    Set split frequency for a band in Hz"
	echo "  set-solo               Enable/disable solo for a band"
	echo "  set-mute               Enable/disable mute for a band"
	echo "  set-band-enabled       Enable/disable a band"
	echo "  set-band-compressor    Enable/disable the compressor of a band"
	echo ""
	echo "set-input-gain / set-output-gain options:"
	echo "  -g <gain_value>        Gain value to set (dB)"
	echo ""
	echo "set-gains options:"
	echo "  -f <gain_file>         Gain file (JSON)"
	echo ""
	echo "set-makeup-gain options:"
	echo "  -b <band>              Band number (0-7)"
	echo "  -g <gain_value>        Gain value to set (dB)"
	echo ""
	echo "set-split-frequency options:"
	echo "  -b <band>              Band number (1-7)"
	echo "  -f <frequency>         Split frequency (Hz)"
	echo ""
	echo "set-solo / set-mute / set-band-compressor options:"
	echo "  -b <band>              Band number (0-7)"
	echo "  -v <value>             Enable/disable (1/0)"
	echo ""
	echo "set-band-enabled options:"
	echo "  -b <band>              Band number (1-7, band 0 is always enabled)"
	echo "  -v <value>             Enable/disable (1/0)"
	echo ""
	echo "Environment:"
	echo "  MB_COMPRESSOR          Compressor node name in the chain (default: multiband_compressor_0)"
	echo ""
	echo "Example:"
	echo "  $0 <node_name> set-makeup-gain -b 2 -g 3"
}

require_band() {
	local band=$1
	local min=$2

	if ! [[ $band =~ ^[0-7]$ ]] || ((band < min)); then
		log "ERROR" "Band must be a number between $min and 7, got '$band'."
		exit 1
	fi
}

require_number() {
	local name=$1
	local value=$2

	if ! is_number "$value"; then
		log "ERROR" "$name must be a number, got '$value'."
		exit 1
	fi
}

require_switch() {
	local value=$1

	if [ "$value" != "0" ] && [ "$value" != "1" ]; then
		log "ERROR" "Value must be 0 or 1, got '$value'."
		exit 1
	fi
}

enable() {
	log "INFO" "Enabling multiband compressor $MB_COMPRESSOR on node $node_id"

	set_props_param "$node_id" "$MB_COMPRESSOR:enabled" 1
}

disable() {
	log "INFO" "Disabling multiband compressor $MB_COMPRESSOR on node $node_id"

	set_props_param "$node_id" "$MB_COMPRESSOR:enabled" 0
}

set_gains() {
	local OPTIND=1
	local gain_file=""
	local value
	shift # past node_id
	while getopts "f:" options; do
		case ${options} in
		f)
			gain_file="$OPTARG"
			;;
		*)
			log "ERROR" "Usage: $0 <node_name> set-gains -f <gain_file>"
			exit 1
			;;
		esac
	done

	if [ ! -s "$gain_file" ]; then
		log "ERROR" "gain_file is required."
		log "ERROR" "Usage: $0 <node_name> set-gains -f <gain_file>"
		exit 1
	fi

	value=$(jq -r '."input-gain" // empty' "$gain_file")
	if [ -n "$value" ]; then
		set_input_gain "$node_id" -g "$value"
	fi

	value=$(jq -r '."output-gain" // empty' "$gain_file")
	if [ -n "$value" ]; then
		set_output_gain "$node_id" -g "$value"
	fi

	for ((i = 0; i < 8; i++)); do
		if ((i != 0)); then
			value=$(jq -r ".band${i}.\"split-frequency\" // empty" "$gain_file")
			if [ -n "$value" ]; then
				set_split_frequency "$node_id" -b "$i" -f "$value"
			fi
		fi

		value=$(jq -r ".band${i}.makeup // empty" "$gain_file")
		if [ -n "$value" ]; then
			set_makeup_gain "$node_id" -b "$i" -g "$value"
		fi
	done
}

set_gain_param() {
	local label=$1
	local param=$2
	local OPTIND=1
	local gain_value=""
	shift 3 # past label, param, node_id
	while getopts "g:" options; do
		case ${options} in
		g)
			gain_value=$OPTARG
			;;
		*)
			log "ERROR" "Usage: $0 <node_name> set-$label-gain -g <gain_value>"
			exit 1
			;;
		esac
	done

	if [ -z "$gain_value" ]; then
		log "ERROR" "gain_value is required."
		log "ERROR" "Usage: $0 <node_name> set-$label-gain -g <gain_value>"
		exit 1
	fi

	require_number "gain_value" "$gain_value"

	log "INFO" "Setting $label gain to $gain_value dB on node $node_id"

	set_props_param "$node_id" "$MB_COMPRESSOR:$param" "$(db_to_linear "$gain_value")"
}

set_input_gain() {
	set_gain_param "input" "g_in" "$@"
}

set_output_gain() {
	set_gain_param "output" "g_out" "$@"
}

set_makeup_gain() {
	local OPTIND=1
	local band=""
	local gain_value=""
	shift # past node_id
	while getopts "b:g:" options; do
		case ${options} in
		b)
			band=$OPTARG
			;;
		g)
			gain_value=$OPTARG
			;;
		*)
			log "ERROR" "Usage: $0 <node_name> set-makeup-gain -b <band> -g <gain_value>"
			exit 1
			;;
		esac
	done

	if [ -z "$band" ] || [ -z "$gain_value" ]; then
		log "ERROR" "Both band and gain_value are required."
		log "ERROR" "Usage: $0 <node_name> set-makeup-gain -b <band> -g <gain_value>"
		exit 1
	fi

	require_band "$band" 0
	require_number "gain_value" "$gain_value"

	log "INFO" "Setting makeup gain for band $band to $gain_value dB on node $node_id"

	set_props_param "$node_id" "$MB_COMPRESSOR:mk_$band" "$(db_to_linear "$gain_value")"
}

set_split_frequency() {
	local OPTIND=1
	local band=""
	local frequency=""
	shift # past node_id
	while getopts "b:f:" options; do
		case ${options} in
		b)
			band=$OPTARG
			;;
		f)
			frequency=$OPTARG
			;;
		*)
			log "ERROR" "Usage: $0 <node_name> set-split-frequency -b <band> -f <frequency>"
			exit 1
			;;
		esac
	done

	if [ -z "$band" ] || [ -z "$frequency" ]; then
		log "ERROR" "Both band and frequency are required."
		log "ERROR" "Usage: $0 <node_name> set-split-frequency -b <band> -f <frequency>"
		exit 1
	fi

	require_band "$band" 1
	require_number "frequency" "$frequency"

	log "INFO" "Setting split frequency for band $band to $frequency Hz on node $node_id"

	set_props_param "$node_id" "$MB_COMPRESSOR:sf_$band" "$frequency"
}

# Shared by the per-band on/off subcommands: set_band_switch <subcommand> <port_prefix> <min_band> <node_id> [options]
set_band_switch() {
	local subcommand=$1
	local port_prefix=$2
	local min_band=$3
	local OPTIND=1
	local band=""
	local value=""
	shift 4 # past subcommand, port_prefix, min_band, node_id
	while getopts "b:v:" options; do
		case ${options} in
		b)
			band=$OPTARG
			;;
		v)
			value=$OPTARG
			;;
		*)
			log "ERROR" "Usage: $0 <node_name> $subcommand -b <band> -v <value>"
			exit 1
			;;
		esac
	done

	if [ -z "$band" ] || [ -z "$value" ]; then
		log "ERROR" "Both band and value are required."
		log "ERROR" "Usage: $0 <node_name> $subcommand -b <band> -v <value>"
		exit 1
	fi

	require_band "$band" "$min_band"
	require_switch "$value"

	log "INFO" "Setting $subcommand for band $band to $value on node $node_id"

	set_props_param "$node_id" "$MB_COMPRESSOR:${port_prefix}_$band" "$value"
}

main() {
	node_name="$1"
	if [ "${node_name}x" == "x" ]; then
		help
		exit 1
	else
		shift # past node_name
	fi

	subcommand="$1"
	if [ "${subcommand}x" == "x" ]; then
		subcommand="help"
	else
		shift # past sub-command
	fi

	if [ "$subcommand" == "help" ]; then
		help
		exit 0
	fi

	node_id=$(get_pw_node_id_by_name "$node_name")
	if [ -z "$node_id" ]; then
		log "ERROR" "Node with name '$node_name' not found."
		exit 1
	fi

	case $subcommand in
	enable)
		enable
		;;
	disable)
		disable
		;;
	set-input-gain)
		set_input_gain "$node_id" "$@"
		;;
	set-output-gain)
		set_output_gain "$node_id" "$@"
		;;
	set-gains)
		set_gains "$node_id" "$@"
		;;
	set-makeup-gain)
		set_makeup_gain "$node_id" "$@"
		;;
	set-split-frequency)
		set_split_frequency "$node_id" "$@"
		;;
	set-solo)
		set_band_switch "set-solo" "bs" 0 "$node_id" "$@"
		;;
	set-mute)
		set_band_switch "set-mute" "bm" 0 "$node_id" "$@"
		;;
	set-band-enabled)
		set_band_switch "set-band-enabled" "cbe" 1 "$node_id" "$@"
		;;
	set-band-compressor)
		set_band_switch "set-band-compressor" "ce" 0 "$node_id" "$@"
		;;
	*)
		log "ERROR" "Unknown subcommand: $subcommand"
		log "ERROR" "Usage: $0 <node_name> <subcommand> [options]"
		log "ERROR" "Available subcommands: $SUBCOMMANDS"
		exit 1
		;;
	esac
}

main "$@"
exit 0
